window.CODE_INDEX = {"classes":{"AppHeader":{"appearsIn":[["collection","h-widgets","Screen \u00b7 widget composition"],["events","h-widgets","Screen \u00b7 widget composition"],["home-menu","h-widgets","Screen \u00b7 widget composition"],["home","h-widgets","Screen \u00b7 widget composition"],["timeline","h-widgets","Screen \u00b7 widget composition"]],"code":"class AppHeader extends StatelessWidget {\n  const AppHeader({\n    super.key,\n    this.title,\n    this.subtitle,\n    this.showBackBtn = true,\n    this.isTransparent = false,\n    this.onBack,\n    this.trailing,\n    this.backIcon = AppIcons.prev,\n    this.backBtnSemantics,\n  });\n  final String? title;\n  final String? subtitle;\n  final bool showBackBtn;\n  final AppIcons backIcon;\n  final String? backBtnSemantics;\n  final bool isTransparent;\n  final VoidCallback? onBack;\n  final Widget Function(BuildContext context)? trailing;\n\n  @override\n  Widget build(BuildContext context) {\n    return ColoredBox(\n      color: isTransparent ? Colors.transparent : $styles.colors.black,\n      child: SafeArea(\n        bottom: false,\n        child: SizedBox(\n          height: 64 * $styles.scale,\n          child: Stack(\n            children: [\n              MergeSemantics(\n                child: Semantics(\n                  header: true,\n                  child: Center(\n                    child: Column(\n                      mainAxisSize: MainAxisSize.min,\n                      children: [\n                        if (title != null)\n                          Text(\n                            title!.toUpperCase(),\n                            textHeightBehavior: TextHeightBehavior(applyHeightToFirstAscent: false),\n                            style: $styles.text.h4.copyWith(\n                              color: $styles.colors.offWhite,\n                              fontWeight: FontWeight.w500,\n                            ),\n                          ),\n                        if (subtitle != null)\n                          Text(\n                            subtitle!.toUpperCase(),\n                            textHeightBehavior: TextHeightBehavior(applyHeightToFirstAscent: false),\n                            style: $styles.text.title1.copyWith(color: $styles.colors.accent1),\n                          ),\n                      ],\n                    ),\n                  ),\n                ),\n              ),\n              Positioned.fill(\n                child: Center(\n                  child: Row(\n                    children: [\n                      Gap($styles.insets.sm),\n                      if (showBackBtn)\n                        BackBtn(\n                          onPressed: onBack,\n                          icon: backIcon,\n                          semanticLabel: backBtnSemantics,\n                        ),\n                      Spacer(),\n                      if (trailing != null) trailing!.call(context),\n                      Gap($styles.insets.sm),\n                      //if (showBackBtn) Container(width: $styles.insets.lg * 2, alignment: Alignment.centerLeft, child: child),\n                    ],\n                  ),\n                ),\n              ),\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n}","file":"lib/ui/common/controls/app_header.dart","kind":"class","line":4,"members":{"AppHeader":[5,15],"backBtnSemantics":[20,20],"backIcon":[19,19],"build":[25,86],"isTransparent":[21,21],"onBack":[22,22],"showBackBtn":[18,18],"subtitle":[17,17],"title":[16,16],"trailing":[23,23]},"shot":"shots/code/AppHeader.jpg","supers":["StatelessWidget"]},"Debouncer":{"appearsIn":[["timeline","h-classes","Logic \u00b7 class diagram"]],"code":"class Debouncer {\n  Debouncer(this.interval);\n  final Duration interval;\n\n  VoidCallback? _action;\n  Timer? _timer;\n\n  void call(VoidCallback action) {\n    // Let the latest action override whatever was there before\n    _action = action;\n    // Always cancel and restart the timer\n    _timer?.cancel();\n    _timer = Timer(interval, _callAction);\n  }\n\n  void _callAction() {\n    _action?.call(); // If we have an action queued up, complete it.\n    _timer = null;\n  }\n\n  void reset() {\n    _action = null;\n    _timer = null;\n  }\n}","file":"lib/logic/common/debouncer.dart","kind":"class","line":5,"members":{"Debouncer":[6,6],"_action":[9,9],"_callAction":[20,23],"_timer":[10,10],"call":[12,18],"interval":[7,7],"reset":[25,28]},"supers":[]},"GlobalEventsData":{"appearsIn":[["timeline","h-classes","Logic \u00b7 class diagram"]],"code":"class GlobalEventsData {\n  final globalEvents = [\n    TimelineEvent(-2900, $strings.timelineEvent2900bce),\n    TimelineEvent(-2700, $strings.timelineEvent2700bce),\n    TimelineEvent(-2600, $strings.timelineEvent2600bce),\n    TimelineEvent(-2560, $strings.timelineEvent2560bce),\n    TimelineEvent(-2500, $strings.timelineEvent2500bce),\n    TimelineEvent(-2200, $strings.timelineEvent2200bce),\n    TimelineEvent(-2000, $strings.timelineEvent2000bce),\n    TimelineEvent(-1800, $strings.timelineEvent1800bce),\n    TimelineEvent(-890, $strings.timelineEvent890bce),\n    TimelineEvent(-776, $strings.timelineEvent776bce),\n    TimelineEvent(-753, $strings.timelineEvent753bce),\n    TimelineEvent(-447, $strings.timelineEvent447bce),\n    TimelineEvent(-427, $strings.timelineEvent427bce),\n    TimelineEvent(-322, $strings.timelineEvent322bce),\n    TimelineEvent(-200, $strings.timelineEvent200bce),\n    TimelineEvent(-44, $strings.timelineEvent44bce),\n    TimelineEvent(-4, $strings.timelineEvent4bce),\n    TimelineEvent(43, $strings.timelineEvent43ce),\n    TimelineEvent(79, $strings.timelineEvent79ce),\n    TimelineEvent(455, $strings.timelineEvent455ce),\n    TimelineEvent(500, $strings.timelineEvent500ce),\n    TimelineEvent(632, $strings.timelineEvent632ce),\n    TimelineEvent(793, $strings.timelineEvent793ce),\n    TimelineEvent(800, $strings.timelineEvent800ce),\n    TimelineEvent(1001, $strings.timelineEvent1001ce),\n    TimelineEvent(1077, $strings.timelineEvent1077ce),\n    TimelineEvent(1117, $strings.timelineEvent1117ce),\n    TimelineEvent(1199, $strings.timelineEvent1199ce),\n    TimelineEvent(1227, $strings.timelineEvent1227ce),\n    TimelineEvent(1337, $strings.timelineEvent1337ce),\n    TimelineEvent(1347, $strings.timelineEvent1347ce),\n    TimelineEvent(1428, $strings.timelineEvent1428ce),\n    TimelineEvent(1439, $strings.timelineEvent1439ce),\n    TimelineEvent(1492, $strings.timelineEvent1492ce),\n    TimelineEvent(1760, $strings.timelineEvent1760ce),\n    TimelineEvent(1763, $strings.timelineEvent1763ce),\n    TimelineEvent(1783, $strings.timelineEvent1783ce),\n    TimelineEvent(1789, $strings.timelineEvent1789ce),\n    TimelineEvent(1914, $strings.timelineEvent1914ce),\n    TimelineEvent(1929, $strings.timelineEvent1929ce),\n    TimelineEvent(1939, $strings.timelineEvent1939ce),\n    TimelineEvent(1957, $strings.timelineEvent1957ce),\n    TimelineEvent(1969, $strings.timelineEvent1969ce),\n  ];\n}","file":"lib/logic/data/timeline_data.dart","kind":"class","line":9,"members":{"globalEvents":[10,54]},"supers":[]},"TimelineEvent":{"appearsIn":[["timeline","h-classes","Logic \u00b7 class diagram"]],"code":"class TimelineEvent {\n  TimelineEvent(this.year, this.description);\n  final int year;\n  final String description;\n}","file":"lib/logic/data/timeline_data.dart","kind":"class","line":3,"members":{"TimelineEvent":[4,4],"description":[6,6],"year":[5,5]},"supers":[]},"TimelineEventCard":{"appearsIn":[["events","h-widgets","Screen \u00b7 widget composition"],["timeline","h-widgets","Screen \u00b7 widget composition"]],"code":"class TimelineEventCard extends StatelessWidget {\n  const TimelineEventCard({\n    super.key,\n    required this.year,\n    required this.text,\n    this.darkMode = false,\n  });\n  final int year;\n  final String text;\n  final bool darkMode;\n\n  @override\n  Widget build(BuildContext context) {\n    return MergeSemantics(\n      child: Padding(\n        padding: EdgeInsets.only(bottom: $styles.insets.sm),\n        child: DefaultTextColor(\n          color: darkMode ? Colors.white : Colors.black,\n          child: Container(\n            color: darkMode ? $styles.colors.greyStrong : $styles.colors.offWhite,\n            padding: EdgeInsets.all($styles.insets.sm),\n            child: IntrinsicHeight(\n              child: Row(\n                children: [\n                  /// Date\n                  SizedBox(\n                    width: 75,\n                    child: Column(\n                      crossAxisAlignment: CrossAxisAlignment.start,\n                      children: [\n                        Text(\n                          '${year.abs()}',\n                          style: $styles.text.h3.copyWith(fontWeight: FontWeight.w400, height: 1),\n                        ),\n                        Text(StringUtils.getYrSuffix(year), style: $styles.text.bodySmall),\n                      ],\n                    ),\n                  ),\n\n                  /// Divider\n                  Container(width: 1, color: darkMode ? Colors.white : $styles.colors.black),\n\n                  Gap($styles.insets.sm),\n\n                  /// Text content\n                  Expanded(\n                    child: Focus(child: Text(text, style: $styles.text.body)),\n                  ),\n                ],\n              ),\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n}","file":"lib/ui/common/timeline_event_card.dart","kind":"class","line":5,"members":{"TimelineEventCard":[6,11],"build":[16,60],"darkMode":[14,14],"text":[13,13],"year":[12,12]},"shot":"shots/code/TimelineEventCard.jpg","supers":["StatelessWidget"]},"TimelineLogic":{"appearsIn":[["home-menu","h-classes","Logic \u00b7 class diagram"],["home-menu","h-sequence","Jump to a wonder, or switch language \u00b7 sequence"],["index","h-services","Services \u00b7 what the screens talk through"],["splash","h-classes","Logic \u00b7 class diagram"],["timeline","h-classes","Logic \u00b7 class diagram"]],"code":"class TimelineLogic {\n  List<TimelineEvent> events = [];\n\n  void init() {\n    // Create an event for each wonder, and merge it with the list of GlobalEvents\n    events = [\n      ...GlobalEventsData().globalEvents,\n      ...wondersLogic.all.map(\n        (w) => TimelineEvent(\n          w.startYr,\n          $strings.timelineLabelConstruction(w.title),\n        ),\n      ),\n    ];\n  }\n}","file":"lib/logic/timeline_logic.dart","kind":"class","line":4,"members":{"events":[5,5],"init":[7,18]},"supers":[]},"TimelineScreen":{"appearsIn":[["index","h-screens","Screens \u00b7 how the user moves"],["timeline","h-classes","Logic \u00b7 class diagram"],["timeline","h-widgets","Screen \u00b7 widget composition"]],"code":"class TimelineScreen extends StatefulWidget {\n  final WonderType? type;\n\n  const TimelineScreen({super.key, required this.type});\n\n  @override\n  State<TimelineScreen> createState() => _TimelineScreenState();\n}","file":"lib/ui/screens/timeline/timeline_screen.dart","kind":"class","line":34,"members":{"TimelineScreen":[37,37],"createState":[39,40],"type":[35,35]},"shot":"shots/code/TimelineScreen.jpg","supers":["StatefulWidget","_TimelineScreenState"]},"TimelineSection":{"appearsIn":[["timeline","h-widgets","Screen \u00b7 widget composition"]],"code":"class TimelineSection extends StatelessWidget {\n  const TimelineSection(this.data, this.selectedYr, {super.key, required this.selectedWonder});\n  final WonderData data;\n  final int selectedYr;\n  final WonderType? selectedWonder;\n\n  @override\n  Widget build(BuildContext context) {\n    bool isSelected = selectedWonder == data.type;\n    // get a fraction from 0 - 1 based on selected yr and start/end yr of the wonder\n    // 500, 250, 750\n    int startYr = data.startYr, endYr = data.endYr;\n    double fraction = (selectedYr - startYr) / (endYr - startYr);\n    fraction = fraction.clamp(0, 1);\n\n    return Semantics(\n      label:\n          '${data.title}, ${$strings.timelineSemanticDate(\n            StringUtils.formatYr(data.startYr),\n            StringUtils.formatYr(data.endYr),\n          )}',\n      child: IgnorePointerKeepSemantics(\n        child: Container(\n          alignment: Alignment(0, -1 + fraction * 2),\n          padding: EdgeInsets.all($styles.insets.xs),\n          decoration: BoxDecoration(color: data.type.fgColor),\n          child: ClipRRect(\n            borderRadius: BorderRadius.circular(99),\n            child: BlendMask(\n              blendModes: isSelected ? [] : const [BlendMode.luminosity],\n              opacity: .6,\n              child: _buildWonderImage(),\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n\n  Container _buildWonderImage() {\n    return Container(\n      height: 160,\n      decoration: BoxDecoration(\n        color: data.type.bgColor,\n        image: DecorationImage(\n          fit: BoxFit.cover,\n          alignment: Alignment(0, -.5),\n          image: AssetImage(data.type.flattened),\n        ),\n      ),\n    );\n  }\n}","file":"lib/ui/screens/timeline/widgets/_timeline_section.dart","kind":"class","line":3,"members":{"TimelineSection":[4,4],"_buildWonderImage":[42,54],"build":[9,40],"data":[5,5],"selectedWonder":[7,7],"selectedYr":[6,6]},"shot":"shots/code/TimelineSection.jpg","supers":["StatelessWidget"]},"WonderData":{"appearsIn":[["artifacts","h-classes","Logic \u00b7 class diagram"],["editorial","h-classes","Logic \u00b7 class diagram"],["events","h-classes","Logic \u00b7 class diagram"],["home-menu","h-widgets","Screen \u00b7 widget composition"],["home","h-classes","Logic \u00b7 class diagram"],["timeline","h-widgets","Screen \u00b7 widget composition"],["wonder-details","h-classes","Logic \u00b7 class diagram"]],"code":"class WonderData extends Equatable {\n  const WonderData({\n    required this.type,\n    required this.title,\n    required this.subTitle,\n    required this.regionTitle,\n    this.startYr = 0,\n    this.endYr = 0,\n    this.artifactStartYr = 0,\n    this.artifactEndYr = 0,\n    this.artifactCulture = '',\n    this.artifactGeolocation = '',\n    this.lat = 0,\n    this.lng = 0,\n    this.imageIds = const [],\n    required this.unsplashCollectionId,\n    required this.pullQuote1Top,\n    required this.pullQuote1Bottom,\n    required this.pullQuote1Author,\n    this.pullQuote2 = '',\n    this.pullQuote2Author = '',\n    this.callout1 = '',\n    this.callout2 = '',\n    this.facts = const [],\n    required this.historyInfo1,\n    required this.historyInfo2,\n    required this.constructionInfo1,\n    required this.constructionInfo2,\n    required this.locationInfo1,\n    required this.locationInfo2,\n    required this.videoId,\n    this.videoCaption = '',\n    this.mapCaption = '',\n    required this.events,\n    this.highlightArtifacts = const [],\n    this.hiddenArtifacts = const [],\n    this.searchData = const [],\n    this.searchSuggestions = const [],\n  });\n\n  final WonderType type;\n  final String title;\n  final String subTitle;\n  final String regionTitle;\n  final String historyInfo1;\n  final String historyInfo2;\n  final String constructionInfo1;\n  final String constructionInfo2;\n  final String locationInfo1;\n  final String locationInfo2;\n  final String pullQuote1Top;\n  final String pullQuote1Bottom;\n  final String pullQuote1Author;\n  final String pullQuote2;\n  final String pullQuote2Author;\n  final String callout1;\n  final String callout2;\n  final String unsplashCollectionId;\n  final String videoId;\n  final String videoCaption;\n  final String mapCaption;\n  final List<String> imageIds;\n  final List<String> facts;\n  final int startYr;\n  final int endYr;\n  final int artifactStartYr;\n  final int artifactEndYr;\n  final String artifactCulture;\n  final String artifactGeolocation;\n  final double lat;\n  final double lng;\n  final List<String> highlightArtifacts; // IDs used to assemble HighlightsData, should not be used directly\n  final List<String> hiddenArtifacts; // IDs used to assemble CollectibleData, should not be used directly\n  final Map<int, String> events;\n  final List<SearchData> searchData;\n  final List<String> searchSuggestions;\n\n  String get titleWithBreaks => title.replaceFirst(' ', '\\n');\n\n  @override\n  List<Object?> get props => [type, title, historyInfo1, imageIds, facts];\n}","file":"lib/logic/data/wonder_data.dart","kind":"class","line":5,"members":{"WonderData":[6,43],"artifactCulture":[72,72],"artifactEndYr":[71,71],"artifactGeolocation":[73,73],"artifactStartYr":[70,70],"callout1":[60,60],"callout2":[61,61],"constructionInfo1":[51,51],"constructionInfo2":[52,52],"endYr":[69,69],"events":[78,78],"facts":[67,67],"hiddenArtifacts":[77,77],"highlightArtifacts":[76,76],"historyInfo1":[49,49],"historyInfo2":[50,50],"imageIds":[66,66],"lat":[74,74],"lng":[75,75],"locationInfo1":[53,53],"locationInfo2":[54,54],"mapCaption":[65,65],"props":[84,85],"pullQuote1Author":[57,57],"pullQuote1Bottom":[56,56],"pullQuote1Top":[55,55],"pullQuote2":[58,58],"pullQuote2Author":[59,59],"regionTitle":[48,48],"searchData":[79,79],"searchSuggestions":[80,80],"startYr":[68,68],"subTitle":[47,47],"title":[46,46],"titleWithBreaks":[82,82],"type":[45,45],"unsplashCollectionId":[62,62],"videoCaption":[64,64],"videoId":[63,63]},"supers":["Equatable"]},"WondersLogic":{"appearsIn":[["events","h-classes","Logic \u00b7 class diagram"],["events","h-sequence","Read the events and open the global timeline \u00b7 sequence"],["home-menu","h-classes","Logic \u00b7 class diagram"],["home-menu","h-sequence","Jump to a wonder, or switch language \u00b7 sequence"],["home","h-classes","Logic \u00b7 class diagram"],["index","h-services","Services \u00b7 what the screens talk through"],["splash","h-classes","Logic \u00b7 class diagram"],["splash","h-sequence","Launch the app \u00b7 sequence"],["timeline","h-classes","Logic \u00b7 class diagram"],["wonder-details","h-classes","Logic \u00b7 class diagram"],["wonder-details","h-sequence","Open a wonder and switch tabs \u00b7 sequence"]],"code":"class WondersLogic {\n  List<WonderData> all = [];\n\n  final int timelineStartYear = -3000;\n  final int timelineEndYear = 2200;\n\n  WonderData getData(WonderType value) {\n    WonderData? result = all.firstWhereOrNull((w) => w.type == value);\n    if (result == null) throw ('Could not find data for wonder type $value');\n    return result;\n  }\n\n  void init() {\n    all = [\n      GreatWallData(),\n      PetraData(),\n      ColosseumData(),\n      ChichenItzaData(),\n      MachuPicchuData(),\n      TajMahalData(),\n      ChristRedeemerData(),\n      PyramidsGizaData(),\n    ];\n  }\n}","file":"lib/logic/wonders_logic.dart","kind":"class","line":12,"members":{"all":[13,13],"getData":[18,22],"init":[24,35],"timelineEndYear":[16,16],"timelineStartYear":[15,15]},"supers":[]},"WondersTimelineBuilder":{"appearsIn":[["artifacts","h-widgets","Screen \u00b7 widget composition"],["events","h-widgets","Screen \u00b7 widget composition"],["timeline","h-widgets","Screen \u00b7 widget composition"]],"code":"/// Visualizes all of the wonders over time.\n/// Distributes the wonders over multiple \"tracks\" so that they do not overlap.\n/// Provides a builder, so the visual representation of each track entry can be customized\nclass WondersTimelineBuilder extends StatelessWidget {\n  const WondersTimelineBuilder({\n    super.key,\n    this.selectedWonders = const [],\n    this.timelineBuilder,\n    this.axis = Axis.horizontal,\n    this.crossAxisGap,\n    this.minSize = 10,\n  });\n  final List<WonderType> selectedWonders;\n  final Widget Function(BuildContext, WonderData type, bool isSelected)? timelineBuilder;\n  final Axis axis;\n  final double? crossAxisGap;\n  final double minSize;\n  bool get isHz => axis == Axis.horizontal;\n\n  @override\n  Widget build(BuildContext context) {\n    final gap = crossAxisGap ?? $styles.insets.xs;\n    // Depending on axis, we put all the wonders in a hz row, or vt column\n    Widget wrapFlex(List<Widget> c) {\n      c = c.map<Widget>((w) => Expanded(child: w)).toList();\n      return isHz\n          ? SeparatedColumn(\n              verticalDirection: VerticalDirection.up,\n              separatorBuilder: () => Gap(gap),\n              children: c,\n            )\n          : SeparatedRow(separatorBuilder: () => Gap(gap), children: c);\n    }\n\n    return LayoutBuilder(\n      builder: (_, constraints) {\n        /// Builds one timeline track, may contain multiple wonders, but they should not overlap\n        Widget buildSingleTimelineTrack(BuildContext context, List<WonderType> types) {\n          return Stack(\n            clipBehavior: Clip.none,\n            children: types.map(\n              (t) {\n                final data = wondersLogic.getData(t);\n                // To keep the math simple, first figure out a multiplier we can use to convert yrs to pixels.\n                int totalYrs = wondersLogic.timelineEndYear - wondersLogic.timelineStartYear;\n                double pxToYrRatio = totalYrs / ((isHz ? constraints.maxWidth : constraints.maxHeight));\n                // Now we just need to calculate year spans, and then convert them to pixels for the start/end position in the Stack\n                int wonderYrs = data.endYr - data.startYr;\n                int yrsFromStart = data.startYr - wondersLogic.timelineStartYear;\n                double startPx = yrsFromStart / pxToYrRatio;\n                double sizePx = wonderYrs / pxToYrRatio;\n                if (sizePx < minSize) {\n                  double yearDelta = ((minSize - sizePx) / 2);\n                  sizePx = minSize;\n                  startPx -= yearDelta;\n                }\n                final isSelected = selectedWonders.contains(data.type);\n                final child =\n                    timelineBuilder?.call(context, data, isSelected) ?? _DefaultTrackEntry(isSelected: isSelected);\n                return isHz\n                    ? Positioned(left: startPx, width: sizePx, top: 0, bottom: 0, child: child)\n                    : Positioned(top: startPx, height: sizePx, left: 0, right: 0, child: child);\n              },\n            ).toList(),\n          );\n        }\n\n        return wrapFlex([\n          // Track 1\n          buildSingleTimelineTrack(\n            context,\n            [\n              WonderType.greatWall,\n              WonderType.pyramidsGiza,\n              WonderType.christRedeemer,\n            ],\n          ),\n          // Track 2\n          buildSingleTimelineTrack(\n            context,\n            [\n              WonderType.petra,\n              WonderType.machuPicchu,\n            ],\n          ),\n          // Track 3\n          buildSingleTimelineTrack(\n            context,\n            [\n              WonderType.chichenItza,\n              WonderType.tajMahal,\n              WonderType.colosseum,\n            ],\n          ),\n        ]);\n      },\n    );\n  }\n}","file":"lib/ui/common/wonders_timeline_builder.dart","kind":"class","line":4,"members":{"WondersTimelineBuilder":[8,15],"axis":[18,18],"build":[23,101],"crossAxisGap":[19,19],"isHz":[21,21],"minSize":[20,20],"selectedWonders":[16,16],"timelineBuilder":[17,17]},"supers":["StatelessWidget"]},"_AnimatedEraText":{"appearsIn":[["timeline","h-widgets","Screen \u00b7 widget composition"]],"code":"class _AnimatedEraText extends StatelessWidget {\n  const _AnimatedEraText(this.year);\n  final int year;\n\n  @override\n  Widget build(BuildContext context) {\n    String era = StringUtils.getEra(year);\n    final style = $styles.text.body.copyWith(color: $styles.colors.offWhite);\n    return Semantics(\n      liveRegion: true,\n      child: Text(era, style: style),\n    ).maybeAnimate(key: ValueKey(era)).fadeIn().slide(begin: Offset(0, .2));\n  }\n}","file":"lib/ui/screens/timeline/widgets/_animated_era_text.dart","kind":"class","line":3,"members":{"_AnimatedEraText":[4,4],"build":[7,15],"year":[5,5]},"shot":"shots/code/_AnimatedEraText.jpg","supers":["StatelessWidget"]},"_BottomScrubber":{"appearsIn":[["timeline","h-classes","Logic \u00b7 class diagram"],["timeline","h-widgets","Screen \u00b7 widget composition"]],"code":"class _BottomScrubber extends StatelessWidget {\n  const _BottomScrubber(\n    this.scroller, {\n    required this.timelineMinSize,\n    required this.size,\n    required this.selectedWonder,\n  });\n  final ScrollController? scroller;\n  final double timelineMinSize;\n  final double size;\n  final WonderType? selectedWonder;\n\n  /// Calculate what fraction the scroller has travelled\n  double _calculateScrollFraction(ScrollPosition? pos) {\n    if (pos == null || pos.maxScrollExtent == 0) return 0;\n    return pos.pixels / pos.maxScrollExtent;\n  }\n\n  /// Calculates what fraction of the scroller is current visible\n  double _calculateViewPortFraction(ScrollPosition? pos) {\n    if (pos == null) return 1;\n    final viewportSize = pos.viewportDimension;\n    final result = viewportSize / (pos.maxScrollExtent + viewportSize);\n    return result.clamp(0, 1);\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final scroller = this.scroller;\n\n    /// It might take a frame until we receive a valid scroller\n    if (scroller == null) return SizedBox.shrink();\n\n    return LayoutBuilder(\n      builder: (context, constraints) {\n        void handleScrubberPan(DragUpdateDetails details) {\n          final totalWidth = constraints.maxWidth;\n          if (!scroller.hasClients) return;\n          double dragMultiplier = (scroller.position.maxScrollExtent + timelineMinSize) / totalWidth;\n          double newPos = scroller.position.pixels + details.delta.dx * dragMultiplier;\n          scroller.position.jumpTo(newPos.clamp(0, scroller.position.maxScrollExtent));\n        }\n\n        return SizedBox(\n          height: size,\n          child: Stack(\n            children: [\n              /// Timeline background\n              Container(\n                padding: EdgeInsets.all($styles.insets.md),\n                decoration: BoxDecoration(\n                  color: $styles.colors.greyStrong,\n                  borderRadius: BorderRadius.circular($styles.corners.md),\n                ),\n                child: WondersTimelineBuilder(\n                  crossAxisGap: 4,\n                  selectedWonders: selectedWonder != null ? [selectedWonder!] : [],\n                ),\n              ),\n\n              /// Visible area, follows the position of scroller\n              AnimatedBuilder(\n                animation: scroller,\n                builder: (_, _) {\n                  ScrollPosition? pos;\n                  if (scroller.hasClients) pos = scroller.position;\n                  // Get current scroll offset and move the viewport to match\n                  double scrollFraction = _calculateScrollFraction(pos);\n                  double viewPortFraction = _calculateViewPortFraction(pos);\n                  final scrubberAlign = Alignment(-1 + scrollFraction * 2, 0);\n\n                  return Positioned.fill(\n                    child: Semantics(\n                      container: true,\n                      slider: true,\n                      label: $strings.bottomScrubberSemanticTimeline,\n                      // Three-finger swipe left (scrollLeft) moves forward in time, like Flutter's LTR scrollables.\n                      onScrollLeft: () =>\n                          handleScrubberPan(DragUpdateDetails(delta: Offset(10, 0), globalPosition: Offset(0, 0))),\n                      onScrollRight: () =>\n                          handleScrubberPan(DragUpdateDetails(delta: Offset(-10, 0), globalPosition: Offset(0, 0))),\n                      child: GestureDetector(\n                        behavior: HitTestBehavior.translucent,\n                        onPanUpdate: handleScrubberPan,\n\n                        /// Scrub area\n                        child: Align(\n                          alignment: scrubberAlign,\n                          child: FractionallySizedBox(\n                            widthFactor: viewPortFraction,\n                            heightFactor: 1,\n                            child: _buildOutlineBox(context, scrubberAlign),\n                          ),\n                        ),\n                      ),\n                    ),\n                  );\n                },\n              ),\n            ],\n          ),\n        );\n      },\n    );\n  }\n\n  Container _buildOutlineBox(BuildContext context, Alignment alignment) {\n    final borderColor = $styles.colors.white;\n    return Container(\n      decoration: BoxDecoration(border: Border.all(color: borderColor)),\n      child: Align(alignment: alignment, child: DashedLine(vertical: true)),\n    );\n  }\n}","file":"lib/ui/screens/timeline/widgets/_bottom_scrubber.dart","kind":"class","line":3,"members":{"_BottomScrubber":[4,9],"_buildOutlineBox":[109,115],"_calculateScrollFraction":[15,19],"_calculateViewPortFraction":[21,27],"build":[29,107],"scroller":[10,10],"selectedWonder":[13,13],"size":[12,12],"timelineMinSize":[11,11]},"shot":"shots/code/_BottomScrubber.jpg","supers":["StatelessWidget"]},"_DashedDividerWithYear":{"appearsIn":[["timeline","h-widgets","Screen \u00b7 widget composition"]],"code":"class _DashedDividerWithYear extends StatelessWidget {\n  const _DashedDividerWithYear(this.year);\n  final int year;\n\n  @override\n  Widget build(BuildContext context) {\n    int yrGap = 10;\n    final roundedYr = (year / yrGap).round() * yrGap;\n    return Stack(\n      children: [\n        Center(child: DashedLine()),\n        CenterRight(\n          child: FractionalTranslation(\n            translation: Offset(0, -.5),\n            child: MergeSemantics(\n              child: Row(\n                mainAxisSize: MainAxisSize.min,\n                children: [\n                  Text(\n                    '${roundedYr.abs()}',\n                    style: $styles.text.h2.copyWith(\n                      color: $styles.colors.white,\n                      shadows: $styles.shadows.text,\n                    ),\n                  ),\n                  Gap($styles.insets.xs),\n                  Text(\n                    StringUtils.getYrSuffix(roundedYr),\n                    style: $styles.text.body.copyWith(\n                      color: Colors.white,\n                      shadows: $styles.shadows.textStrong,\n                    ),\n                  ),\n                  Gap($styles.insets.xs),\n                ],\n              ),\n            ),\n          ),\n        ),\n      ],\n    );\n  }\n}","file":"lib/ui/screens/timeline/widgets/_dashed_divider_with_year.dart","kind":"class","line":3,"members":{"_DashedDividerWithYear":[4,4],"build":[7,44],"year":[5,5]},"supers":["StatelessWidget"]},"_EventMarker":{"appearsIn":[["timeline","h-widgets","Screen \u00b7 widget composition"]],"code":"/// A dot that represents a single global event.\n/// Animated to a selected state which is is larger in size.\nclass _EventMarker extends StatelessWidget {\n  const _EventMarker(\n    this.offset, {\n    required this.isSelected,\n    required this.event,\n    required this.onPressed,\n  });\n  final double offset;\n  final TimelineEvent event;\n  final bool isSelected;\n  final void Function(TimelineEvent event) onPressed;\n\n  @override\n  Widget build(BuildContext context) {\n    return Align(\n      alignment: Alignment(0, -1 + offset * 2),\n      // Use an OverflowBox wrapped in a zero-height sized box so that al\n      // This allows alignment-based positioning to be accurate even at the edges of the parent.\n      child: SizedBox(\n        height: 0,\n        child: OverflowBox(\n          maxHeight: 30,\n          child: AppBtn.basic(\n            semanticLabel: '${event.year}: ${event.description}',\n            onPressed: () => onPressed(event),\n            child: Container(\n              alignment: Alignment.center,\n              height: 30,\n              child: AnimatedContainer(\n                width: isSelected ? 6 : 2,\n                height: isSelected ? 6 : 2,\n                curve: Curves.easeOutBack,\n                duration: $styles.times.med,\n                decoration: BoxDecoration(\n                  borderRadius: BorderRadius.circular(99),\n                  color: $styles.colors.accent1,\n                  boxShadow: [\n                    BoxShadow(\n                      color: $styles.colors.accent1.withValues(alpha: isSelected ? .5 : 0),\n                      spreadRadius: 3,\n                      blurRadius: 3,\n                    ),\n                  ],\n                ),\n              ),\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n}","file":"lib/ui/screens/timeline/widgets/_event_markers.dart","kind":"class","line":116,"members":{"_EventMarker":[119,124],"build":[130,168],"event":[126,126],"isSelected":[127,127],"offset":[125,125],"onPressed":[128,128]},"supers":["StatelessWidget"]},"_EventMarkers":{"appearsIn":[["timeline","h-widgets","Screen \u00b7 widget composition"]],"code":"/// A vertically aligned stack of dots that represent global events\n/// The event closest to the [selectedYr] param will be visible selected\nclass _EventMarkers extends StatefulWidget {\n  const _EventMarkers(\n    this.selectedYr, {\n    required this.onEventChanged,\n    required this.onMarkerPressed,\n  });\n\n  final void Function(TimelineEvent? event) onEventChanged;\n  final void Function(TimelineEvent event) onMarkerPressed;\n  final int selectedYr;\n\n  @override\n  State<_EventMarkers> createState() => _EventMarkersState();\n}","file":"lib/ui/screens/timeline/widgets/_event_markers.dart","kind":"class","line":3,"members":{"_EventMarkers":[6,10],"createState":[16,17],"onEventChanged":[12,12],"onMarkerPressed":[13,13],"selectedYr":[14,14]},"supers":["StatefulWidget","_EventMarkersState"]},"_EventMarkersState":{"appearsIn":[["timeline","h-classes","Logic \u00b7 class diagram"],["timeline","h-sequence","Open the timeline at a wonder and browse events \u00b7 sequence"]],"code":"class _EventMarkersState extends State<_EventMarkers> {\n  bool get showReferenceMarkers => kDebugMode;\n  int get startYr => wondersLogic.timelineStartYear;\n\n  int get endYr => wondersLogic.timelineEndYear;\n\n  late final int _totalYrs = endYr - startYr;\n\n  TimelineEvent? selectedEvent;\n\n  /// Normalizes a given year to a value from 0 - 1, based on start and end yr.\n  double _calculateOffsetY(int yr) => (yr - startYr) / _totalYrs;\n\n  /// Loops through the global events, and does a px-based check to see whether\n  /// one of them should be selected  (as oppose to year-based proximity).\n  /// This ensures consistent UX at different zoom levels.\n  void _updateSelectedEvent(double maxPxHeight) {\n    const double minDistance = 10;\n    TimelineEvent? closestEvent;\n    double closestDistance = double.infinity;\n    // Convert current yr to a px position\n    double currentYearPx = _calculateOffsetY(widget.selectedYr) * maxPxHeight;\n    for (var e in timelineLogic.events) {\n      // Convert both the event.yr to px, and compare with currentYearPx\n      double eventPx = _calculateOffsetY(e.year) * maxPxHeight;\n      double d = (eventPx - currentYearPx).abs();\n      // Keep the closest event that is within minDistance\n      if (d <= minDistance && d < closestDistance) {\n        closestEvent = e;\n        closestDistance = d;\n      }\n    }\n    // Dispatch if event has actually changed since last time\n    if (closestEvent != selectedEvent) {\n      scheduleMicrotask(() => widget.onEventChanged(closestEvent));\n    }\n    selectedEvent = closestEvent;\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return IgnorePointerKeepSemantics(\n      child: LayoutBuilder(\n        builder: (_, constraints) {\n          /// Figure out which event is \"selected\"\n          _updateSelectedEvent(constraints.maxHeight);\n\n          /// Create a marker for each event\n          List<Widget> markers = timelineLogic.events.map((event) {\n            double offsetY = _calculateOffsetY(event.year);\n            return _EventMarker(\n              offsetY,\n              event: event,\n              isSelected: event == selectedEvent,\n              onPressed: widget.onMarkerPressed,\n            );\n          }).toList();\n\n          /// Stack of fractionally positioned markers\n          return FocusTraversalGroup(\n            policy: WidgetOrderTraversalPolicy(),\n            child: Container(\n              alignment: Alignment.topLeft,\n              padding: EdgeInsets.only(left: 75),\n              child: SizedBox(\n                width: 20,\n                child: Stack(\n                  children: [\n                    ...markers,\n                    if (showReferenceMarkers) ..._buildReferenceMarkers(),\n                  ],\n                ),\n              ),\n            ),\n          );\n        },\n      ),\n    );\n  }\n\n  List<Widget> _buildReferenceMarkers() {\n    final marker = Container(color: Colors.red.withValues(alpha: .4), width: 10, height: 10);\n    return [\n      Align(\n        alignment: Alignment.topCenter,\n        child: FractionalTranslation(translation: Offset(0, -.5), child: marker),\n      ),\n      Align(alignment: Alignment.center, child: marker),\n      Align(\n        alignment: Alignment.bottomCenter,\n        child: FractionalTranslation(translation: Offset(0, .5), child: marker),\n      ),\n    ];\n  }\n}","file":"lib/ui/screens/timeline/widgets/_event_markers.dart","kind":"class","line":20,"members":{"_buildReferenceMarkers":[100,113],"_calculateOffsetY":[30,31],"_totalYrs":[26,26],"_updateSelectedEvent":[33,57],"build":[59,98],"endYr":[24,24],"selectedEvent":[28,28],"showReferenceMarkers":[21,21],"startYr":[22,22]},"supers":["State"]},"_EventPopups":{"appearsIn":[["timeline","h-widgets","Screen \u00b7 widget composition"]],"code":"class _EventPopups extends StatefulWidget {\n  const _EventPopups({required this.currentEvent});\n  final TimelineEvent? currentEvent;\n\n  @override\n  State<_EventPopups> createState() => _EventPopupsState();\n}","file":"lib/ui/screens/timeline/widgets/_event_popups.dart","kind":"class","line":3,"members":{"_EventPopups":[4,4],"createState":[7,8],"currentEvent":[5,5]},"supers":["StatefulWidget","_EventPopupsState"]},"_EventPopupsState":{"appearsIn":[["timeline","h-classes","Logic \u00b7 class diagram"],["timeline","h-sequence","Open the timeline at a wonder and browse events \u00b7 sequence"]],"code":"class _EventPopupsState extends State<_EventPopups> {\n  final _debouncer = Debouncer(500.animateMs);\n  TimelineEvent? _eventToShow;\n\n  @override\n  void dispose() {\n    _debouncer.reset();\n    super.dispose();\n  }\n\n  @override\n  void didUpdateWidget(covariant _EventPopups oldWidget) {\n    super.didUpdateWidget(oldWidget);\n    _debouncer.call(showCardForCurrentYr);\n  }\n\n  void showCardForCurrentYr() {\n    setState(() {\n      _eventToShow = widget.currentEvent;\n    });\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final evt = _eventToShow;\n    return TopCenter(\n      child: ClipRect(\n        child: IgnorePointerKeepSemantics(\n          child: AnimatedSwitcher(\n            duration: $styles.times.fast,\n            child: evt == null\n                ? SizedBox.shrink()\n                : Semantics(\n                    liveRegion: true,\n                    child: Animate(\n                      effects: const [\n                        SlideEffect(begin: Offset(0, -.1)),\n                      ],\n                      key: ValueKey(_eventToShow?.year),\n                      child: IntrinsicHeight(\n                        child: SizedBox(\n                          width: $styles.sizes.maxContentWidth3,\n                          child: Padding(\n                            padding: EdgeInsets.all($styles.insets.md),\n                            child: TimelineEventCard(\n                              text: evt.description,\n                              year: evt.year,\n                            ),\n                          ),\n                        ),\n                      ),\n                    ),\n                  ),\n          ),\n        ),\n      ),\n    );\n  }\n}","file":"lib/ui/screens/timeline/widgets/_event_popups.dart","kind":"class","line":11,"members":{"_debouncer":[12,12],"_eventToShow":[13,13],"build":[33,68],"didUpdateWidget":[21,25],"dispose":[15,19],"showCardForCurrentYr":[27,31]},"supers":["State"]},"_ScalingViewportState":{"appearsIn":[["timeline","h-classes","Logic \u00b7 class diagram"],["timeline","h-sequence","Open the timeline at a wonder and browse events \u00b7 sequence"]],"code":"class _ScalingViewportState extends State<_ScrollingViewport> {\n  late final _ScrollingViewportController controller = _ScrollingViewportController(this);\n  static const double _minTimelineSize = 100;\n  final _currentEventMarker = ValueNotifier<TimelineEvent?>(null);\n  Size? _prevSize;\n\n  @override\n  void initState() {\n    super.initState();\n    controller.init();\n    widget.onInit?.call(controller);\n  }\n\n  @override\n  void dispose() {\n    controller.dispose();\n    super.dispose();\n  }\n\n  void _handleEventMarkerChanged(TimelineEvent? event) {\n    _currentEventMarker.value = event;\n    AppHaptics.selectionClick();\n  }\n\n  void _handleMarkerPressed(event) {\n    final pos = controller.calculateScrollPosFromYear(event.year);\n    controller.scroller.animateTo(pos, duration: $styles.times.med, curve: Curves.easeOutBack);\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    if (_prevSize != null && _prevSize != context.mq.size) {\n      scheduleMicrotask(controller._handleResize);\n    }\n    _prevSize = context.mq.size;\n    return Listener(\n      onPointerSignal: (PointerSignalEvent e) {\n        if (HardwareKeyboard.instance.isControlPressed) {\n          controller._handleScaleUpdateMouse(((e as PointerScaleEvent).scale - 1) * 0.25);\n        }\n      },\n      child: GestureDetector(\n        // Handle pinch to zoom\n        onScaleUpdate: controller._handleScaleUpdate,\n        onScaleStart: controller._handleScaleStart,\n        behavior: HitTestBehavior.translucent,\n        // Fade in entire view when first shown\n        child: Stack(\n          children: [\n            // Main content area\n            _buildScrollingArea(context).maybeAnimate().fadeIn(),\n\n            // Dashed line with a year that changes as we scroll\n            IgnorePointerKeepSemantics(\n              child: AnimatedBuilder(\n                animation: controller.scroller,\n                builder: (_, _) {\n                  return _DashedDividerWithYear(controller.calculateYearFromScrollPos());\n                },\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n\n  Widget _buildScrollingArea(BuildContext context) {\n    // Builds a TimelineSection, and passes it the currently selected yr based on scroll position.\n    // Rebuilds when timeline is scrolled.\n    Widget buildTimelineSection(WonderData data) {\n      return ClipRRect(\n        borderRadius: BorderRadius.circular(99),\n        child: AnimatedBuilder(\n          animation: controller.scroller,\n          builder: (_, _) => TimelineSection(\n            data,\n            controller.calculateYearFromScrollPos(),\n            selectedWonder: widget.selectedWonder,\n          ),\n        ),\n      );\n    }\n\n    return LayoutBuilder(\n      builder: (_, constraints) {\n        // cache constraints, so they can be used to maintain the selected year while zooming\n        controller._constraints = constraints;\n        double vtPadding = constraints.maxHeight / 2;\n        double height = controller.calculateContentHeight();\n        final width = min($styles.sizes.maxContentWidth2, constraints.maxWidth);\n        return Stack(\n          children: [\n            SingleChildScrollView(\n              controller: controller.scroller,\n              padding: EdgeInsets.symmetric(vertical: vtPadding),\n              // A stack inside a SizedBox which sets its overall height\n              child: CenteredBox(\n                height: height,\n                width: width,\n                child: Stack(\n                  children: [\n                    /// Year Markers\n                    _YearMarkers(),\n\n                    /// individual timeline sections\n                    Positioned.fill(\n                      left: 100,\n                      right: $styles.insets.sm,\n                      child: FocusTraversalGroup(\n                        //child: Placeholder(),\n                        child: WondersTimelineBuilder(\n                          axis: Axis.vertical,\n                          crossAxisGap: max(6, (width - (120 * 3)) / 2),\n                          minSize: _minTimelineSize,\n                          timelineBuilder: (_, data, _) => buildTimelineSection(data),\n                        ),\n                      ),\n                    ),\n\n                    /// Event Markers, rebuilds on scroll\n                    AnimatedBuilder(\n                      animation: controller.scroller,\n                      builder: (_, _) => _EventMarkers(\n                        controller.calculateYearFromScrollPos(),\n                        onEventChanged: _handleEventMarkerChanged,\n                        onMarkerPressed: _handleMarkerPressed,\n                      ),\n                    ),\n                  ],\n                ),\n              ),\n            ),\n\n            /// Top and bottom gradients for visual style\n            ListOverscollGradient(),\n            BottomCenter(\n              child: ListOverscollGradient(bottomUp: true),\n            ),\n\n            /// Event Popups, rebuilds when [_currentEventMarker] changes\n            ValueListenableBuilder<TimelineEvent?>(\n              valueListenable: _currentEventMarker,\n              builder: (_, data, _) {\n                return _EventPopups(currentEvent: data);\n              },\n            ),\n          ],\n        );\n      },\n    );\n  }\n}","file":"lib/ui/screens/timeline/widgets/_scrolling_viewport.dart","kind":"class","line":22,"members":{"_buildScrollingArea":[89,173],"_currentEventMarker":[25,25],"_handleEventMarkerChanged":[41,44],"_handleMarkerPressed":[46,49],"_minTimelineSize":[24,24],"_prevSize":[26,26],"build":[51,87],"controller":[23,23],"dispose":[35,39],"initState":[28,33]},"supers":["State"]},"_ScrollingViewport":{"appearsIn":[["timeline","h-widgets","Screen \u00b7 widget composition"]],"code":"class _ScrollingViewport extends StatefulWidget {\n  const _ScrollingViewport({\n    required this.scroller,\n    required this.minSize,\n    required this.maxSize,\n    required this.selectedWonder,\n    this.onYearChanged,\n  }) : onInit = null;\n  final double minSize;\n  final double maxSize;\n  final ScrollController scroller;\n  final WonderType? selectedWonder;\n  final void Function(int year)? onYearChanged;\n  final void Function(_ScrollingViewportController controller)? onInit;\n\n  @override\n  State<_ScrollingViewport> createState() => _ScalingViewportState();\n}","file":"lib/ui/screens/timeline/widgets/_scrolling_viewport.dart","kind":"class","line":3,"members":{"_ScrollingViewport":[4,10],"createState":[18,19],"maxSize":[12,12],"minSize":[11,11],"onInit":[16,16],"onYearChanged":[15,15],"scroller":[13,13],"selectedWonder":[14,14]},"shot":"shots/code/_ScrollingViewport.jpg","supers":["StatefulWidget"]},"_ScrollingViewportController":{"appearsIn":[["timeline","h-classes","Logic \u00b7 class diagram"],["timeline","h-sequence","Open the timeline at a wonder and browse events \u00b7 sequence"]],"code":"class _ScrollingViewportController extends ChangeNotifier {\n  _ScrollingViewportController(this.state);\n  final _ScalingViewportState state;\n\n  int get startYr => wondersLogic.timelineStartYear;\n  int get endYr => wondersLogic.timelineEndYear;\n\n  double _zoom = .5;\n  double _zoomOnScaleStart = 0;\n  late BoxConstraints _constraints;\n  _ScrollingViewport get widget => state.widget;\n  ScrollController get scroller => widget.scroller;\n  late final ValueNotifier<int> _currentYr = ValueNotifier(startYr)\n    ..addListener(\n      () => state.widget.onYearChanged?.call(_currentYr.value),\n    );\n\n  void init() {\n    scheduleMicrotask(() {\n      setZoom(.5);\n      final w = widget.selectedWonder;\n      if (w != null) {\n        final data = wondersLogic.getData(w);\n        final pos = calculateScrollPosFromYear(data.startYr);\n        scroller.jumpTo(pos - 200);\n        scroller.animateTo(pos, duration: $styles.times.extraSlow, curve: Curves.easeOutCubic);\n        scroller.addListener(_updateCurrentYear);\n      }\n    });\n  }\n\n  void _updateCurrentYear() => _currentYr.value = calculateYearFromScrollPos();\n\n  /// Allows ancestors to set zoom directly\n  void setZoom(double d) {\n    // ignore: invalid_use_of_protected_member\n    state.setState(() {\n      // Determine current yr, based on scroll position\n      int currentYr = calculateYearFromScrollPos();\n\n      // Change zoom, which will scale our content, and change our scroll position\n      _zoom = d;\n      _zoom = _zoom.clamp(0, 1.0);\n      // Jump to whatever yr we were on before changing the zoom\n      jumpToYear(currentYr);\n    });\n  }\n\n  /// Jump to the scroll position for a given yr. Does not animated.\n  void jumpToYear(int yr, {bool animate = false}) {\n    double yrRatio = (yr - startYr) / (endYr - startYr);\n    double newMaxScroll = calculateContentHeight();\n    final newPos = newMaxScroll * yrRatio;\n    if (animate) {\n      scroller.animateTo(newPos, duration: $styles.times.med, curve: Curves.easeOut);\n    } else {\n      scroller.jumpTo(newPos);\n    }\n  }\n\n  /// Calculates current content height, taking zoom into account.\n  double calculateContentHeight() {\n    //double minSize = 300;\n    double vtPadding = _constraints.maxHeight / 2;\n    return lerpDouble(widget.minSize - vtPadding, widget.maxSize, _zoom) ?? widget.maxSize;\n  }\n\n  /// Derive current yr based on the scroll position and the current content height.\n  int calculateYearFromScrollPos() {\n    if (scroller.hasClients == false) return startYr;\n    int totalYrs = endYr - startYr;\n    double currentPx = scroller.position.pixels;\n    double scrollAmt = currentPx / calculateContentHeight();\n    int result = (startYr + scrollAmt * totalYrs).round();\n    return result.clamp(startYr, endYr);\n  }\n\n  double calculateScrollPosFromYear(int yr) {\n    int totalYrs = endYr - startYr;\n    double yrFraction = totalYrs / (yr - startYr);\n    return calculateContentHeight() / yrFraction;\n  }\n\n  /// Since the onScale gesture always starts from 1, we need to hold onto the zoom\n  /// value that we had when the scale gesture started and multiply it with the gesture data, to get the real new scale.\n  void _handleScaleStart(ScaleStartDetails _) => _zoomOnScaleStart = _zoom;\n\n  void _handleScaleUpdate(ScaleUpdateDetails details) {\n    setZoom(details.scale * _zoomOnScaleStart);\n  }\n\n  void _handleScaleUpdateMouse(double scale) {\n    setZoom(Math.max(0, Math.min(1, _zoom + scale)));\n  }\n\n  /// Maintain current yr when the app changes size\n  void _handleResize() => jumpToYear(_currentYr.value);\n}","file":"lib/ui/screens/timeline/widgets/_scrolling_viewport_controller.dart","kind":"class","line":3,"members":{"_ScrollingViewportController":[4,4],"_constraints":[12,12],"_currentYr":[15,18],"_handleResize":[98,99],"_handleScaleStart":[86,88],"_handleScaleUpdate":[90,92],"_handleScaleUpdateMouse":[94,96],"_updateCurrentYear":[34,34],"_zoom":[10,10],"_zoomOnScaleStart":[11,11],"calculateContentHeight":[63,68],"calculateScrollPosFromYear":[80,84],"calculateYearFromScrollPos":[70,78],"endYr":[8,8],"init":[20,32],"jumpToYear":[51,61],"scroller":[14,14],"setZoom":[36,49],"startYr":[7,7],"state":[5,5],"widget":[13,13]},"supers":["ChangeNotifier"]},"_TimelineScreenState":{"appearsIn":[["timeline","h-classes","Logic \u00b7 class diagram"],["timeline","h-sequence","Open the timeline at a wonder and browse events \u00b7 sequence"]],"code":"class _TimelineScreenState extends State<TimelineScreen> {\n  /// Create a scroll controller that the top and bottom timelines can share\n  final ScrollController _scroller = ScrollController();\n  final _year = ValueNotifier<int>(0);\n\n  void _handleViewportYearChanged(int value) => _year.value = value;\n\n  @override\n  Widget build(BuildContext context) {\n    return LayoutBuilder(\n      builder: (_, constraints) {\n        // Determine min and max size of the timeline based on the size available to this widget\n        const double scrubberSize = 80;\n        const double minSize = 1200;\n        const double maxSize = 5500;\n        return Container(\n          color: $styles.colors.black,\n          child: Padding(\n            padding: EdgeInsets.only(bottom: 0),\n            child: Column(\n              children: [\n                AppHeader(title: $strings.timelineTitleGlobalTimeline),\n\n                /// Vertically scrolling timeline, manages a ScrollController.\n                Expanded(\n                  child: _ScrollingViewport(\n                    scroller: _scroller,\n                    minSize: minSize,\n                    maxSize: maxSize,\n                    selectedWonder: widget.type,\n                    onYearChanged: _handleViewportYearChanged,\n                  ),\n                ),\n\n                /// Era Text (classical, modern etc)\n                ValueListenableBuilder<int>(\n                  valueListenable: _year,\n                  builder: (_, value, _) => _AnimatedEraText(value),\n                ),\n                Gap($styles.insets.xs),\n\n                /// Mini Horizontal timeline, reacts to the state of the larger scrolling timeline,\n                /// and changes the timelines scroll position on Hz drag\n                CenteredBox(\n                  width: $styles.sizes.maxContentWidth1,\n                  child: Padding(\n                    padding: EdgeInsets.symmetric(horizontal: $styles.insets.lg),\n                    child: _BottomScrubber(\n                      _scroller,\n                      size: scrubberSize,\n                      timelineMinSize: minSize,\n                      selectedWonder: widget.type,\n                    ),\n                  ),\n                ),\n                Gap($styles.insets.lg),\n              ],\n            ),\n          ),\n        );\n      },\n    );\n  }\n}","file":"lib/ui/screens/timeline/timeline_screen.dart","kind":"class","line":43,"members":{"_handleViewportYearChanged":[48,48],"_scroller":[44,45],"_year":[46,46],"build":[50,105]},"supers":["State"]},"_YearMarkers":{"appearsIn":[["timeline","h-widgets","Screen \u00b7 widget composition"]],"code":"class _YearMarkers extends StatelessWidget {\n  _YearMarkers();\n\n  int get startYr => wondersLogic.timelineStartYear;\n  int get endYr => wondersLogic.timelineEndYear;\n\n  late final int _totalYrs = endYr - startYr;\n\n  /// Normalizes a given year to a value from 0 - 1, based on start and end yr.\n  double _calculateOffsetY(int yr) => (yr - startYr) / _totalYrs;\n\n  @override\n  Widget build(BuildContext context) {\n    return IgnorePointerKeepSemantics(\n      child: LayoutBuilder(\n        builder: (_, constraints) {\n          int interval = 100;\n          if (constraints.maxHeight < 800) {\n            interval = 500;\n          } else if (constraints.maxHeight < 1500) {\n            interval = 250;\n          }\n\n          // If interval is 100 and time is 0 - 1000 yrs, make a list of 11 items:\n          // [0, 100, 200, ..., 1000 ]\n          int numMarkers = (_totalYrs / interval).round() + 1;\n          late final markers = List.generate(numMarkers, (i) {\n            return startYr + i * interval;\n          });\n\n          return SizedBox(\n            width: 100,\n            child: AnimatedSwitcher(\n              duration: $styles.times.med,\n              child: Stack(\n                key: ValueKey(interval),\n                children: markers.map((yr) {\n                  return _YearMarker(yr, _calculateOffsetY(yr));\n                }).toList(),\n              ),\n            ),\n          );\n        },\n      ),\n    );\n  }\n}","file":"lib/ui/screens/timeline/widgets/_year_markers.dart","kind":"class","line":3,"members":{"_YearMarkers":[4,4],"_calculateOffsetY":[11,12],"_totalYrs":[9,9],"build":[14,48],"endYr":[7,7],"startYr":[6,6]},"supers":["StatelessWidget"]}},"sourceUrl":"https://github.com/gskinnerTeam/flutter-wonderous-app/blob/30ccc36a276223ebbb85dbb290d6ff2facf001ed/"};
